<template><div class="page"><div class="section-title"><div><h2>维护文档</h2><span class="muted">管理集群架构、运维手册、故障预案和变更规范</span></div><div style="display:flex;gap:10px"><n-button @click="load">刷新</n-button><n-upload :show-file-list="false" accept=".md" :custom-request="upload"><n-button type="primary" :loading="uploading">上传维护文档</n-button></n-upload></div></div><div class="panel" style="display:flex;gap:12px;flex-wrap:wrap"><n-input v-model:value="keyword" clearable placeholder="搜索标题、描述或标签" style="width:260px"/><n-select v-model:value="type" clearable placeholder="文档类型" :options="typeOptions" style="width:180px"/></div><div class="metric-grid" style="grid-template-columns:repeat(6,1fr)"><div class="metric" v-for="m in metrics" :key="m.label"><div><div class="metric-value">{{m.value}}</div><div class="metric-label">{{m.label}}</div></div></div></div><div class="panel"><n-data-table :columns="columns" :data="filtered" :loading="loading" :pagination="{pageSize:10}"/></div><n-drawer v-model:show="preview" :width="720"><n-drawer-content v-if="selected" :title="selected.document.title"><n-space vertical><n-descriptions bordered :column="1"><n-descriptions-item label="类型">{{typeLabel(selected.document.type)}}</n-descriptions-item><n-descriptions-item label="描述">{{selected.document.description||'暂无描述'}}</n-descriptions-item><n-descriptions-item label="标签">{{(selected.document.tags||[]).join('、')||'暂无标签'}}</n-descriptions-item></n-descriptions><pre class="log-window">{{selected.content}}</pre><n-button type="primary" @click="askAgent">让 Agent 分析本文档</n-button></n-space></n-drawer-content></n-drawer></div></template>
<script setup>import {h,ref,computed,onMounted} from 'vue';import {useRouter} from 'vue-router';import {maintenanceDocumentApi} from '@/api';const router=useRouter(),docs=ref([]),loading=ref(false),uploading=ref(false),keyword=ref(''),type=ref(null),preview=ref(false),selected=ref(null);const types=[['cluster-architecture','集群架构'],['operations-manual','运维手册'],['incident-runbook','故障预案'],['change-standard','变更规范']],typeOptions=types.map(([value,label])=>({value,label})),typeLabel=t=>types.find(x=>x[0]===t)?.[1]||t;const filtered=computed(()=>docs.value.filter(d=>(!type.value||d.type===type.value)&&(!keyword.value||`${d.title} ${d.description} ${(d.tags||[]).join(' ')}`.toLowerCase().includes(keyword.value.toLowerCase()))));const metrics=computed(()=>[{label:'文档总数',value:docs.value.length},{label:'集群架构',value:docs.value.filter(d=>d.type===types[0][0]).length},{label:'运维手册',value:docs.value.filter(d=>d.type===types[1][0]).length},{label:'故障预案',value:docs.value.filter(d=>d.type===types[2][0]).length},{label:'变更规范',value:docs.value.filter(d=>d.type===types[3][0]).length},{label:'已索引',value:docs.value.filter(d=>d.indexed).length}]);const columns=[{title:'标题',key:'title'},{title:'类型',key:'type',render:r=>typeLabel(r.type)},{title:'描述',key:'description',ellipsis:{tooltip:true}},{title:'标签',key:'tags',render:r=>(r.tags||[]).join('、')},{title:'大小',key:'size',render:r=>formatSize(r.size)},{title:'索引状态',key:'indexed',render:r=>r.indexed?'已索引':'待处理'},{title:'操作',key:'action',render:r=>h('span',{},[h('button',{class:'link-button',onClick:()=>open(r.name)},'预览'),h('button',{class:'link-button',style:'margin-left:10px',onClick:()=>remove(r.name)},'删除')])}];function formatSize(n){if(n<1024)return`${n} B`;if(n<1048576)return`${(n/1024).toFixed(1)} KB`;return`${(n/1048576).toFixed(1)} MB`}async function load(){loading.value=true;try{docs.value=(await maintenanceDocumentApi.list()).documents||[]}finally{loading.value=false}}async function open(name){selected.value=await maintenanceDocumentApi.get(name);preview.value=true}async function upload({file,onFinish,onError}){if(!file.file.name.toLowerCase().endsWith('.md')){onError();return}uploading.value=true;try{await maintenanceDocumentApi.upload(file.file);onFinish();await load()}catch(e){onError(e)}finally{uploading.value=false}}async function remove(name){if(!confirm(`确定删除 ${name}？`))return;await maintenanceDocumentApi.remove(name);await load()}function askAgent(){router.push({path:'/app/chat',query:{prompt:`请分析维护文档：${selected.value.document.title}`}})}onMounted(load)</script>
